INSERT INTO CODE
	 ( ID
	 , NAME
	 , CRT_DT
	 , MDFY_DT
	 , PARENT_ID
	 , "ORDER"
	 , USE_YN
	 )
VALUES(#{registCode.id}
	 , #{registCode.name}
	 , SYSDATE
	 , SYSDATE
	 , #{registCode.parentId}
	 , #{registCode.order}
	 , NVL(#{registCode.useYn},'Y'))

mapper.update:
UPDATE CODE
   SET NAME = #{modCode.name}
     , PARENT_ID = #{modCode.parentId}
     , "ORDER" = #{modCode.order}
     , USE_YN = #{modCode.useYn}
     , MDFY_DT = SYSDATE
 WHERE ID = #{codeId}

mapper.select:
SELECT NVL(MAX("ORDER"), -1) AS MAX_ORDER FROM CODE
WHERE PARENT_ID IS NULL
WHERE PARENT_ID = #{parentId}

SELECT ID , NAME , CRT_DT , MDFY_DT , PARENT_ID , "ORDER" , USE_YN FROM CODE WHERE "ORDER" = #{order}
AND PARENT_ID IS NULL
AND PARENT_ID = #{parentId}
AND ID != #{codeId}
AND ROWNUM = 1

mapper.update:
UPDATE CODE
   SET "ORDER" = #{lastOrder}
	 , MDFY_DT = SYSDATE
 WHERE ID = #{id}
